package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import java.util.stream.Collectors;
import net.officefloor.hq.app.AuditUser;
import net.officefloor.hq.app.claim.ClaimFigures;
import net.officefloor.hq.app.claim.ClaimLogRepository;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonGrade;
import net.officefloor.hq.app.person.PersonGradeRepository;
import net.officefloor.hq.app.person.PersonGrades;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestHeader;

/** Closes the period, fixing each person's due-total for it as it is now — the dues (with any late charge, as shown now) of the claims whose due-by falls in it that counted by the status they had at the end of its last day (not a person's
 *  unbound OPEN ones dated within a hold of theirs), added up, skipping n/a, 0.00 for one with none — and its own, their sum. A soft-closed period can be closed, fixing them afresh. Refuses a period already closed, and a close by a role the sheet's permission matrix does not
 *  allow to (by the standing rule, clerk and steward may). */
public class ClosePeriod {
    public void close(@Val Period period, PeriodRepository repository, ClaimRepository claims, PersonRepository people,
            RateRepository rates, SheetRepository sheets, PersonGradeRepository grades, ClaimLogRepository log,
            RoleRepository roles, @RequestHeader(name = "X-User", required = false) String user) throws InvalidPeriodException {
        Sheet sheet = sheets.findById(period.getSheetId()).orElseGet(() -> new Sheet(period.getSheetId()));
        String role = roles.roleOf(period.getSheetId(), AuditUser.decode(user));
        if (!sheet.allows("close", role)) {
            throw new InvalidPeriodException("A " + role + " cannot close a period.");
        }
        if (period.isClosed()) {
            throw new InvalidPeriodException("The period is already closed.");
        }
        period.close(totals(period, sheet, claims, people, rates, grades, log));
        repository.saveAndFlush(period);
    }

    /** Closes the period on the sheet, fixing each person's due-total for it as it is now (see above). */
    static void fix(Period period, Sheet sheet, ClaimRepository claims, PersonRepository people, RateRepository rates,
            PersonGradeRepository grades, ClaimLogRepository log) {
        period.close(totals(period, sheet, claims, people, rates, grades, log));
    }

    /** Each person's due-total for the period as it is now (see above), by person id. */
    static Map<Long, BigDecimal> totals(Period period, Sheet sheet, ClaimRepository claims, PersonRepository people,
            RateRepository rates, PersonGradeRepository grades, ClaimLogRepository log) {
        Map<Long, Person> byId = people.findBySheetIdOrderByIdAsc(period.getSheetId()).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
        var sheetRates = rates.findBySheetIdOrderByGradeAscFromDateAscIdAsc(period.getSheetId());
        Map<Long, List<PersonGrade>> dated = grades.datedOnSheet(period.getSheetId());
        Map<Long, ClaimStatus> then = log.statusesOn(period.getSheetId(), period.getToDate());
        Map<Long, BigDecimal> totals = new HashMap<>();
        byId.keySet().forEach(id -> totals.put(id, BigDecimal.ZERO.setScale(2)));
        claims.findBySheetIdOrderByIdDesc(period.getSheetId()).stream()
                .filter(c -> byId.containsKey(c.getPersonId()) && ClaimFigures.countsAsOf(c, then.get(c.getId()), byId.get(c.getPersonId()), sheet.getToday())
                        && period.contains(c.getDueBy()))
                .forEach(c -> {
                    BigDecimal due = new ClaimFigures(sheetRates, new PersonGrades(byId.get(c.getPersonId()).getGrade(),
                            dated.getOrDefault(c.getPersonId(), List.of())), sheet).due(c);
                    if (due != null) {
                        totals.merge(c.getPersonId(), due, BigDecimal::add);
                    }
                });
        totals.replaceAll((id, t) -> t.setScale(2));
        return totals;
    }
}
package net.officefloor.hq.app.history;

import com.fasterxml.jackson.annotation.JsonAutoDetect.Visibility;
import com.fasterxml.jackson.annotation.PropertyAccessor;
import java.sql.Date;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Function;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.person.Patron;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonGrade;
import net.officefloor.hq.app.role.Delegation;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.statement.Statement;
import net.officefloor.hq.app.watch.Watch;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import tools.jackson.databind.DeserializationFeature;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.json.JsonMapper;

/**
 * The states a sheet's things have been saved in (entity_history), each with the sheet's today when it was saved —
 * recorded by HistoryRecorder — and read back as they stood at the end of a date: the last state saved while the
 * sheet's today was on or before it. A thing with no state saved by then did not exist then (or was deleted); one
 * with no state recorded at all was saved before this was kept and stands as it is.
 */
@Service
public class History {

    /** The kind each kept entity is recorded under. */
    private static final Map<Class<?>, String> KINDS = Map.of(Claim.class, "claim", Person.class, "person",
            PersonGrade.class, "person-grade", Period.class, "period", Patron.class, "patron", Watch.class, "watch",
            Role.class, "role", Delegation.class, "delegation", Statement.class, "statement");

    /** An entity's state as its fields hold it: every field, no getter. */
    private final JsonMapper json = JsonMapper.builder()
            .changeDefaultVisibility(v -> v.withVisibility(PropertyAccessor.ALL, Visibility.NONE)
                    .withVisibility(PropertyAccessor.FIELD, Visibility.ANY))
            .disable(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES)
            .build();

    private final JdbcTemplate jdbc;

    public History(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The kind an entity is recorded under; null for one that is not kept. */
    static String kindOf(Class<?> type) {
        return KINDS.get(type);
    }

    /** The entity's state, as recorded. */
    JsonNode stateOf(Object entity) {
        return json.valueToTree(entity);
    }

    String write(JsonNode state) {
        return json.writeValueAsString(state);
    }

    /**
     * The sheet's things of a type as they stood at the end of a date, in no particular order: each as its last
     * state saved while the sheet's today was on or before it; none deleted or not yet made by then. A thing with no
     * state recorded at all is taken as it stands now. Only worked out, never saved.
     *
     * @param current the sheet's things of the type as they stand now.
     */
    public <T> List<T> asOf(String sheetId, Class<T> type, LocalDate date, List<T> current, Function<T, Long> idOf) {
        Set<Long> recorded = new HashSet<>();
        Map<Long, String> then = new LinkedHashMap<>();
        jdbc.query("SELECT entity_id, made_on, state FROM entity_history WHERE sheet_id = ? AND kind = ? ORDER BY id",
                rs -> {
                    long id = rs.getLong(1);
                    recorded.add(id);
                    Date madeOn = rs.getDate(2);
                    if (!madeOn.toLocalDate().isAfter(date)) {
                        String state = rs.getString(3);
                        if (state == null) {
                            then.remove(id);
                        } else {
                            then.put(id, state);
                        }
                    }
                }, sheetId, kindOf(type));
        List<T> asOf = new ArrayList<>();
        for (T now : current) {
            if (!recorded.contains(idOf.apply(now))) {
                asOf.add(now);
            }
        }
        then.values().forEach(state -> asOf.add(json.readValue(state, type)));
        return asOf;
    }
}
-- Every state a sheet's claim, person, dated grade, period, patron, watch, role, delegation and statement has been
-- saved in, with the sheet's today when it was saved, in the order saved: the last one saved while the sheet's today
-- was on or before a date gives the thing as it stood at the end of that date (an as-of view). A null state: it was
-- deleted then. A thing with no state recorded was saved before this was kept, and stands as it is as of any date.
CREATE TABLE entity_history (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL,
    kind VARCHAR(40) NOT NULL,
    entity_id BIGINT NOT NULL,
    made_on DATE NOT NULL,
    state CLOB
);
CREATE INDEX entity_history_sheet ON entity_history (sheet_id, kind, id);
-- The sheet's today when it was archived (null: not archived, or not recorded).
ALTER TABLE sheet ADD COLUMN archived_on DATE;

